// ---- Traits with default implementations ----

// ---- A trait with default methods ----
trait Describable {
    // Required method (no default)
    fn name(&self) -> String;

    // Default implementation
    fn description(&self) -> String {
        format!("An object named '{}'", self.name())
    }

    // Default implementation with default
    fn short_description(&self) -> String {
        self.name()
    }

    // Default implementation that calls other methods
    fn full_description(&self) -> String {
        format!("{}\n  {}", self.name(), self.description())
    }
}

// ---- A trait with more default methods ----
trait Attackable {
    fn attack_power(&self) -> i32;

    // Default: uses attack_power
    fn attack(&self, target: &mut impl Damageable) {
        let damage = self.attack_power();
        target.take_damage(damage);
    }

    // Default: uses attack_power with multiplier
    fn special_attack(&self, target: &mut impl Damageable) {
        let damage = self.attack_power() * 2;
        target.take_damage(damage);
    }
}

// ---- Trait with default for all methods ----
trait Empty {
    fn do_something(&self) {}
    fn do_another(&self) {}
}

// ---- Implementing Describable for a struct ----
struct Player {
    name: String,
    health: i32,
    level: i32,
}

impl Describable for Player {
    // Only need to implement name()
    fn name(&self) -> String {
        self.name.clone()
    }

    // Override description() with custom implementation
    fn description(&self) -> String {
        format!("A level {} player named {}", self.level, self.name)
    }
}

// ---- Implementing Describable for another struct ----
struct Enemy {
    name: String,
    health: i32,
    is_boss: bool,
}

impl Describable for Enemy {
    // Only need to implement name()
    fn name(&self) -> String {
        self.name.clone()
    }

    // Use default description()
}

// ---- Implementing Attackable ----
struct Warrior {
    name: String,
    strength: i32,
}

impl Attackable for Warrior {
    fn attack_power(&self) -> i32 {
        self.strength * 2
    }
}

struct Mage {
    name: String,
    magic_power: i32,
}

impl Attackable for Mage {
    fn attack_power(&self) -> i32 {
        self.magic_power * 3
    }

    // Override special_attack
    fn special_attack(&self, target: &mut impl Damageable) {
        let damage = self.magic_power * 5;
        target.take_damage(damage);
    }
}

// ---- Damageable trait for the example ----
trait Damageable {
    fn take_damage(&mut self, damage: i32);
}

impl Damageable for Player {
    fn take_damage(&mut self, damage: i32) {
        self.health -= damage;
        if self.health < 0 {
            self.health = 0;
        }
        println!("{} took {} damage! HP: {}", self.name, damage, self.health);
    }
}

fn main() {
    // ---- Player with custom description ----
    let player = Player {
        name: String::from("Hero"),
        health: 100,
        level: 5,
    };

    println!("Name: {}", player.name());
    println!("Description: {}", player.description());
    println!("Short: {}", player.short_description());
    println!("Full:\n{}", player.full_description());

    // ---- Enemy with default description ----
    let enemy = Enemy {
        name: String::from("Goblin"),
        health: 30,
        is_boss: false,
    };

    println!("\nEnemy Name: {}", enemy.name());
    println!("Enemy Description: {}", enemy.description());

    // ---- Warrior with default attack ----
    let mut target = Player {
        name: String::from("Target"),
        health: 100,
        level: 1,
    };

    let warrior = Warrior {
        name: String::from("Warrior"),
        strength: 15,
    };

    println!("\n--- Warrior Attack ---");
    warrior.attack(&mut target);

    // ---- Mage with overridden special_attack ----
    let mut target2 = Player {
        name: String::from("Target2"),
        health: 100,
        level: 1,
    };

    let mage = Mage {
        name: String::from("Mage"),
        magic_power: 12,
    };

    println!("\n--- Mage Attack ---");
    mage.attack(&mut target2);
    mage.special_attack(&mut target2);
}

